-- Agrega linkVideo a Receta y RecetaPlantilla: un link directo a una
-- busqueda dentro del canal de YouTube de Alvaro Barrientos Montero para
-- esa receta (no se referencia un video puntual porque no hay forma de
-- confirmar que exista uno especifico para cada plato -- la busqueda
-- dentro del canal siempre es un link real y util).
ALTER TABLE "RecetaPlantilla" ADD COLUMN "linkVideo" TEXT;
ALTER TABLE "Receta" ADD COLUMN "linkVideo" TEXT;

